/**
 * The single catalogue of user-facing text (M-1..M-40, docs/user-stories.md).
 * UI code never hard-codes text: it reads it from here.
 * Templates keep their placeholders ({n}, {total}, …); helpers below fill them.
 */

import { formatMarks } from './logic/format';
import type { Gap } from './logic/gap';
import type { EarnedCode, PassCode, TotalCode } from './validation/validate';

export const MESSAGE_IDS = [
  'M-1', 'M-2', 'M-3', 'M-4', 'M-5', 'M-6', 'M-7', 'M-8', 'M-9', 'M-10',
  'M-11', 'M-12', 'M-13', 'M-14', 'M-15', 'M-16', 'M-17', 'M-18', 'M-19', 'M-20',
  'M-21', 'M-22', 'M-23', 'M-24', 'M-25', 'M-26', 'M-27', 'M-28', 'M-29', 'M-30',
  'M-31', 'M-32', 'M-33', 'M-34', 'M-35', 'M-36', 'M-37', 'M-38', 'M-39', 'M-40',
] as const;

export type MessageId = (typeof MESSAGE_IDS)[number];

export const MESSAGES = {
  // Result area and verdict
  'M-1': 'Enter marks earned and total marks possible to see the score.',
  'M-2': 'Enter a pass mark to see whether this is a pass or a fail.',
  'M-3': 'The score will appear once every entry is valid.',
  'M-4': 'Pass',
  'M-5': 'Fail',
  // Gap line ({n}: at most 2 dp, trailing zeros trimmed, comma thousands)
  'M-6': '{n} marks short of the pass mark',
  'M-7': '1 mark short of the pass mark',
  'M-8': '{n} marks above the pass mark',
  'M-9': '1 mark above the pass mark',
  'M-10': 'Exactly on the pass mark',
  'M-11': 'Less than 0.01 marks above the pass mark',
  // Under marks earned
  'M-12': 'Marks earned must be a number, like 17.5.',
  'M-13': "Marks earned can't be negative.",
  'M-14': 'Marks earned can have at most 2 decimal places.',
  'M-15': "Marks earned can't be more than the total marks possible.",
  // Under total marks possible
  'M-16': 'Total marks possible must be a number, like 23.',
  'M-17': "Total marks possible can't be negative.",
  'M-18': 'Total marks possible can have at most 2 decimal places.',
  'M-19': 'Total marks possible must be more than 0.',
  'M-20': "Total marks possible can't be more than 1,000,000.",
  // Under pass mark
  'M-21': 'Pass mark must be a number, like 70.',
  'M-22': "Pass mark can't be negative.",
  'M-23': 'Pass mark can have at most 1 decimal place.',
  'M-24': "Pass mark can't be more than 100.",
  // Actions (M-26..M-29 are for future stories S-5, S-6)
  'M-25': 'Next learner',
  'M-26': 'Copy outcome',
  'M-27': 'Outcome copied.',
  'M-28': '{earned} of {total} marks: {score}, {verdict}, {gap line}',
  'M-29': 'Marks needed to pass: {n} of {total}',
  // Page and card text (DEC-11)
  'M-30': 'Quiz score and pass-mark calculator',
  'M-31': 'Quiz score',
  'M-32': 'Check a quiz result',
  'M-33': 'A score at or above the pass mark is a pass.',
  'M-34': 'Marks earned',
  'M-35': 'Total marks possible',
  'M-36': 'Pass mark',
  'M-37': ' (percent)',
  'M-38': '%',
  'M-39': 'Score',
  'M-40': 'or press Esc',
} as const satisfies Record<MessageId, string>;

/** The key name at the end of M-40, shown in a <kbd> element. */
export const ESC_KEY_LABEL = 'Esc';

/** The unit after a score ("76.0%"): the same percent sign as M-38. */
export const SCORE_UNIT = MESSAGES['M-38'];

/** A score as read out: "76.0" → "76.0%". */
export function scoreText(score: string): string {
  return `${score}${SCORE_UNIT}`;
}

/** Joins the parts of a screen-reader announcement (ui-design.md §Accessibility): "76.0%, Pass". */
export function announcementText(parts: ReadonlyArray<string>): string {
  return parts.join(', ');
}

/** Error codes per field (technical-design.md §Validation). */
export interface FieldCodes {
  readonly earned: EarnedCode;
  readonly total: TotalCode;
  readonly pass: PassCode;
}

export type FieldName = keyof FieldCodes;

type ErrorMessageTable = { readonly [F in FieldName]: Readonly<Record<FieldCodes[F], MessageId>> };

/** (field, code) → the one message shown under that field (M-12..M-24, technical-design.md §Validation). */
export const ERROR_MESSAGE_IDS: ErrorMessageTable = {
  earned: { NOT_NUMBER: 'M-12', NEGATIVE: 'M-13', TOO_MANY_DP: 'M-14', OVER_TOTAL: 'M-15' },
  total: { NOT_NUMBER: 'M-16', NEGATIVE: 'M-17', TOO_MANY_DP: 'M-18', ZERO: 'M-19', TOO_LARGE: 'M-20' },
  pass: { NOT_NUMBER: 'M-21', NEGATIVE: 'M-22', TOO_MANY_DP: 'M-23', TOO_LARGE: 'M-24' },
};

/** The text shown under `field` for an error `code`. */
export function errorText<F extends FieldName>(field: F, code: FieldCodes[F]): string {
  return MESSAGES[ERROR_MESSAGE_IDS[field][code]];
}

/** The error-state announcement: each field's message, then M-3 (ui-design.md §Accessibility). They are sentences. */
export function errorAnnouncementText(fieldMessages: ReadonlyArray<string>): string {
  return [...fieldMessages, MESSAGES['M-3']].join(' ');
}

/** One mark, in hundredths: the only value that takes the singular "mark" (A-11). */
const ONE_MARK = 100;

/** The gap line (M-6..M-11) for a gap, with {n} filled by `formatMarks` (A-10, A-11). */
export function gapText(gap: Gap): string {
  switch (gap.kind) {
    case 'exact':
      return MESSAGES['M-10'];
    case 'aboveTiny':
      return MESSAGES['M-11'];
    case 'short':
      return gap.h === ONE_MARK ? MESSAGES['M-7'] : MESSAGES['M-6'].replace('{n}', formatMarks(gap.h));
    case 'above':
      return gap.h === ONE_MARK ? MESSAGES['M-9'] : MESSAGES['M-8'].replace('{n}', formatMarks(gap.h));
  }
}
import { test as base, expect } from '@playwright/test';

// DoD: any console error, console warning or uncaught page error fails the test.
export const test = base.extend<{ consoleGuard: void }>({
  consoleGuard: [
    async ({ page }, use) => {
      const problems: string[] = [];
      page.on('console', (msg) => {
        if (msg.type() === 'error' || msg.type() === 'warning') {
          problems.push(`console.${msg.type()}: ${msg.text()}`);
        }
      });
      page.on('pageerror', (err) => problems.push(`pageerror: ${err.message}`));
      await use();
      expect(problems, 'console errors, warnings or page errors').toEqual([]);
    },
    { auto: true },
  ],
});

export { expect };
import type { Locator, Page } from '@playwright/test';
import { test, expect } from './fixtures';
import { MESSAGES } from '../../src/messages';

// S-1 Score and pass/fail verdict (test-plan.md E-S1.1..E-S1.8).
// Numbers are quoted exactly from the ACs; words come from messages.ts (M-4 "Pass", M-5 "Fail").

const PASS = MESSAGES['M-4'];
const FAIL = MESSAGES['M-5'];

interface Card {
  earned: Locator;
  total: Locator;
  pass: Locator;
  result: Locator;
  score: Locator;
  verdict: Locator;
  status: Locator;
}

function card(page: Page): Card {
  const result = page.getByRole('region', { name: MESSAGES['M-39'] });
  return {
    earned: page.getByLabel(MESSAGES['M-34'], { exact: true }),
    total: page.getByLabel(MESSAGES['M-35'], { exact: true }),
    pass: page.getByLabel(MESSAGES['M-36'] + MESSAGES['M-37'], { exact: true }),
    result,
    score: result.locator('.score'),
    verdict: result.locator('.verdict'),
    status: page.getByRole('status'),
  };
}

/** Score and verdict as the user sees them; the verdict also carries its icon and colour class. */
async function expectOutcome(c: Card, score: string, verdict: string): Promise<void> {
  await expect(c.score).toHaveText(score);
  await expect(c.verdict).toHaveText(verdict);
  await expect(c.verdict).toHaveClass(new RegExp(`verdict--${verdict === PASS ? 'pass' : 'fail'}`));
  await expect(c.verdict.locator('svg')).toHaveAttribute('aria-hidden', 'true');
  await expect(c.result).not.toContainText(MESSAGES['M-1']);
}

async function enter(c: Card, earned: string, total: string, pass?: string): Promise<void> {
  if (pass !== undefined) await c.pass.fill(pass);
  await c.total.fill(total);
  await c.earned.fill(earned);
}

test.beforeEach(async ({ page }) => {
  await page.goto('./');
});

test('E-S1.1 typing "17.5" of "23" with the pre-filled "70" shows "76.0%" and "Pass" with no button or key', async ({ page }) => {
  const c = card(page);
  await expect(c.pass).toHaveValue('70');
  await expect(c.score).toHaveCount(0);

  await c.earned.pressSequentially('17.5');
  await expect(c.result).toContainText(MESSAGES['M-1']);
  await c.total.pressSequentially('23');

  await expectOutcome(c, '76.0%', PASS);
  // The "%" is the half-size unit of the score.
  await expect(c.score.locator('.score-unit')).toHaveText('%');
  // Screen readers get the same outcome after the debounce.
  await expect(c.status).toContainText(`76.0%, ${PASS}`);
});

test('E-S1.2 "17.5" of "25" (exactly 70%) shows "70.0%" and "Pass"', async ({ page }) => {
  const c = card(page);
  await enter(c, '17.5', '25');
  await expectOutcome(c, '70.0%', PASS);
});

test('E-S1.3 "17.49" of "25" (69.96%) shows "69.9%" and "Fail", never "70.0%"', async ({ page }) => {
  const c = card(page);
  await c.total.fill('25');
  await c.earned.focus();
  const afterEachKey: Array<[string, string]> = [
    ['1', '4.0%'],
    ['7', '68.0%'],
    ['.', '68.0%'],
    ['4', '69.6%'],
    ['9', '69.9%'],
  ];
  for (const [key, score] of afterEachKey) {
    await page.keyboard.type(key);
    await expect(c.score).toHaveText(score);
    await expect(c.result).not.toContainText('70.0%');
  }
  await expect(c.earned).toHaveValue('17.49');
  await expectOutcome(c, '69.9%', FAIL);
});

test('E-S1.4 "2" of "3" shows "66.6%" (rounded down, not "66.7%") and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '2', '3');
  await expectOutcome(c, '66.6%', FAIL);
  await expect(c.result).not.toContainText('66.7%');
});

test('E-S1.5 pass mark "0": "0" of "23" → "0.0%" Pass; pass mark "100": "23" of "23" → "100.0%" Pass', async ({ page }) => {
  const c = card(page);
  await enter(c, '0', '23', '0');
  await expectOutcome(c, '0.0%', PASS);

  await enter(c, '23', '23', '100');
  await expectOutcome(c, '100.0%', PASS);
});

test('E-S1.6 pass mark "100": "999999.99" of "1000000" shows "99.9%" and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '999999.99', '1000000', '100');
  await expectOutcome(c, '99.9%', FAIL);
});

test('E-S1.7 "0.01" of "1000000" with pass mark "70" shows "0.0%" and "Fail"', async ({ page }) => {
  const c = card(page);
  await enter(c, '0.01', '1000000', '70');
  await expectOutcome(c, '0.0%', FAIL);
});

test('E-S1.8 after "76.0%" Pass, earned "15.5" → "67.3%" Fail; then pass mark "65" → Pass, score stays "67.3%"', async ({ page }) => {
  const c = card(page);
  await enter(c, '17.5', '23');
  await expectOutcome(c, '76.0%', PASS);

  await c.earned.fill('15.5');
  await expectOutcome(c, '67.3%', FAIL);

  await c.pass.fill('65');
  await expectOutcome(c, '67.3%', PASS);
  await expect(c.earned).toHaveValue('15.5');
  await expect(c.total).toHaveValue('23');
});
import { defineConfig, devices } from '@playwright/test';

const PORT = 4173;
const BASE_URL = `http://127.0.0.1:${PORT}/`;
const isCI = Boolean(process.env['CI']);

// ADR-005: e2e runs against the production build served by `vite preview`.
export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: true,
  forbidOnly: isCI,
  retries: 0, // never mask failures with retries, locally or in CI
  // CI also writes a JSON report; scripts/ci-summary.mjs turns it into per-engine check annotations.
  reporter: isCI
    ? [['list'], ['html', { open: 'never' }], ['json', { outputFile: 'test-results/e2e-results.json' }]]
    : 'list',
  use: {
    baseURL: BASE_URL,
    trace: 'retain-on-failure',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
  ],
  webServer: {
    command: `npm run build && npm run preview -- --host 127.0.0.1 --port ${PORT} --strictPort`,
    url: BASE_URL,
    reuseExistingServer: !isCI,
    timeout: 120_000,
  },
});
