// String → scaled integer, without parseFloat or Number() (technical-design.md §Decimal strategy, ADR-002).

export type ParseCode = 'NOT_NUMBER' | 'NEGATIVE' | 'TOO_MANY_DP';

/** `value` is the number × 10^maxDp as an exact integer; `null` means the field is empty. */
export type ParseResult = { ok: true; value: number | null } | { ok: false; code: ParseCode };

/** Above every limit (1,000,000 × 100 and 100 × 10), so a saturated value only ever fails a range check. */
export const OVER_LIMIT = 1_000_000_000_000;

/** More integer digits than this saturate to OVER_LIMIT, keeping every value a safe integer. */
const MAX_INT_DIGITS = 9;

/** Digits with at most one dot (A-13); the integer or fraction part may be empty. */
const DECIMAL = /^(\d*)(?:\.(\d*))?$/;

/** Folds a string of ASCII digits into an integer, one digit at a time. */
function digitsValue(digits: string): number {
  let value = 0;
  for (let i = 0; i < digits.length; i += 1) value = value * 10 + (digits.charCodeAt(i) - 48);
  return value;
}

/**
 * Checks, in A-15 order: not a number → negative → too many decimal places.
 * Spaces around the text are ignored; "" and a lone "." are empty (A-18); a lone "-" is negative (A-18).
 */
export function parseDecimal(raw: string, maxDp: number): ParseResult {
  const text = raw.trim();
  if (text === '' || text === '.') return { ok: true, value: null };

  const negative = text.startsWith('-');
  const match = DECIMAL.exec(negative ? text.slice(1) : text);
  if (match === null) return { ok: false, code: 'NOT_NUMBER' };
  if (negative) return { ok: false, code: 'NEGATIVE' };

  const intDigits = (match[1] ?? '').replace(/^0+/, '');
  const fracDigits = match[2] ?? '';
  if (fracDigits.length > maxDp) return { ok: false, code: 'TOO_MANY_DP' };
  if (intDigits.length > MAX_INT_DIGITS) return { ok: true, value: OVER_LIMIT };

  return { ok: true, value: digitsValue(intDigits + fracDigits.padEnd(maxDp, '0')) };
}
import { parseDecimal, type ParseCode } from './parse';

// Per-field checks in A-15 order (technical-design.md §Validation). Nothing throws; every result is typed.

export type EarnedCode = ParseCode | 'OVER_TOTAL';
export type TotalCode = ParseCode | 'ZERO' | 'TOO_LARGE';
export type PassCode = ParseCode | 'TOO_LARGE';

/** `value` is a scaled integer (earned and total × 100, pass mark × 10); `null` = empty field. */
export type FieldResult<Code> = { ok: true; value: number | null } | { ok: false; code: Code };

export interface RawFields {
  readonly earned: string;
  readonly total: string;
  readonly pass: string;
}

export interface ValidatedFields {
  readonly earned: FieldResult<EarnedCode>;
  readonly total: FieldResult<TotalCode>;
  readonly pass: FieldResult<PassCode>;
}

const MARKS_DP = 2; // A-4
const PASS_DP = 1; // A-6
const TOTAL_MAX = 100_000_000; // 1,000,000 marks × 100 (A-5)
const PASS_MAX = 1000; // 100 % × 10 (A-6)

function validateTotal(raw: string): FieldResult<TotalCode> {
  const parsed = parseDecimal(raw, MARKS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (parsed.value === 0) return { ok: false, code: 'ZERO' };
  if (parsed.value > TOTAL_MAX) return { ok: false, code: 'TOO_LARGE' };
  return parsed;
}

function validatePass(raw: string): FieldResult<PassCode> {
  const parsed = parseDecimal(raw, PASS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (parsed.value > PASS_MAX) return { ok: false, code: 'TOO_LARGE' };
  return parsed;
}

/** Marks earned ≤ total is checked only when both are otherwise valid and filled in (A-15). */
function validateEarned(raw: string, total: FieldResult<TotalCode>): FieldResult<EarnedCode> {
  const parsed = parseDecimal(raw, MARKS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (total.ok && total.value !== null && parsed.value > total.value) return { ok: false, code: 'OVER_TOTAL' };
  return parsed;
}

export function validateInputs(raw: RawFields): ValidatedFields {
  const total = validateTotal(raw.total);
  return { earned: validateEarned(raw.earned, total), total, pass: validatePass(raw.pass) };
}
